import React, { useState } from "react";
import axios from "axios";
import Message from "./Message";
import VoiceButton from "./VoiceButton";

const ChatBox = () => {
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState([]);

  const handleSend = async () => {
    if (!input) return;

    setMessages([...messages, { text: input, isUser: true }]);
    setInput("");

    try {
      const res = await axios.post("http://localhost:5000/chat", { prompt: input });
      setMessages([...messages, { text: input, isUser: true }, { text: res.data.response.parts[0].text, isUser: false }]);
    } catch (error) {
      setMessages([...messages, { text: "Error fetching response", isUser: false }]);
    }
  };

  return (
    <div className="container">
      <div>
        {messages.map((msg, index) => (
          <div key={index}>
            <Message text={msg.text} isUser={msg.isUser} />
            {!msg.isUser && <VoiceButton text={msg.text} />}
          </div>
        ))}
      </div>
      <textarea value={input} onChange={(e) => setInput(e.target.value)} placeholder="Ask me anything..." />
      <br />
      <button onClick={handleSend} className="btn btn-primary">Send</button>
    </div>
  );
};

export default ChatBox;
